    const makeMaps = (pairs) => {
      const enToFr = new Map();
      const frToEn = new Map();
      for (const [en, fr] of pairs) { enToFr.set(en, fr); frToEn.set(fr, en); }
      return { enToFr, frToEn };
    };
    const textMaps = makeMaps(textPairs);
    const messageMaps = makeMaps(messagePairs);
    const protocolMaps = makeMaps(protocolPairs.map(([fr, en]) => [en, fr]));

    function detect() {
      let locale = '';
      let source = 'fallback-en';
      try {
        const store = globalThis.BdApi?.Webpack?.getStore?.('LocaleStore');
        const candidates = [
          store?.locale,
          typeof store?.getLocale === 'function' ? store.getLocale() : '',
          typeof store?.getState === 'function' ? store.getState()?.locale : '',
        ];
        locale = String(candidates.find((value) => typeof value === 'string' && value.trim()) || '').trim();
        if (locale) source = 'Discord.LocaleStore';
      } catch (_) {}
      if (!locale) {
        try {
          const htmlLang = String(document?.documentElement?.getAttribute?.('lang') || '').trim();
          if (htmlLang) { locale = htmlLang; source = 'document.documentElement.lang'; }
        } catch (_) {}
      }
      const french = /^fr(?:[-_]|$)/i.test(locale);
      return { locale: locale || 'unknown', language: french ? 'fr' : 'en', source, fallbackEnglish: !french };
    }

    const isFrench = () => detect().language === 'fr';
    const pick = (english, french) => isFrench() ? french : english;

    function translateExact(value, maps) {
      const raw = String(value ?? '');
      const trimmed = raw.trim();
      if (!trimmed) return raw;
      const translated = isFrench() ? maps.enToFr.get(trimmed) : maps.frToEn.get(trimmed);
      if (!translated) return raw;
      const start = raw.indexOf(trimmed);
      return start >= 0 ? raw.slice(0, start) + translated + raw.slice(start + trimmed.length) : translated;
    }

    function translateText(value) {
      const raw = String(value ?? '');
      const exact = translateExact(raw, textMaps);
      if (exact !== raw) return exact;
      if (isFrench()) {
        let m;
        if ((m = /^Today at\s+(.+)$/.exec(raw.trim()))) return `Aujourd’hui à ${m[1]}`;
        if ((m = /^Identity:\s*(.+)$/.exec(raw.trim()))) return `Identité : ${m[1]}`;
        if ((m = /^Group identity trust:\s*(.+)$/.exec(raw.trim()))) return `Confiance d’identité du groupe : ${m[1]}`;
        if ((m = /^Maximum\s+(\d+)\s+characters$/.exec(raw.trim()))) return `Maximum ${m[1]} caractères`;
        if ((m = /^Minimum\s+(\d+)\s+· must differ from the question · never transmitted$/.exec(raw.trim()))) return `Minimum ${m[1]} · doit être différente de la question · jamais transmise`;
        if ((m = /^SDC identity — (.+) — (.+)\. Click to open verification\.$/.exec(raw.trim()))) return `Identité SDC — ${m[1]} — ${m[2]}. Cliquer pour ouvrir la vérification.`;
      } else {
        let m;
        if ((m = /^Aujourd’hui à\s+(.+)$/.exec(raw.trim()))) return `Today at ${m[1]}`;
      }
      return raw;
    }
    function translateProtocolText(value) { return translateExact(value, protocolMaps); }

    function localizeMessage(value) {
      let out = translateExact(value, messageMaps);
      if (out !== String(value ?? '')) return out;
      const raw = String(value ?? '');
      if (isFrench()) {
        let m;
        if ((m = /^Auto-lock: (.+)$/.exec(raw))) return `Verrouillage auto : ${translateText(m[1])}`;
        if ((m = /^Key exchange re-authorized for (.+) — next request still requires confirmation$/.exec(raw))) return `Échange de clés réautorisé pour ${m[1]} — la prochaine demande exigera toujours une confirmation`;
        if ((m = /^Would you like to initiate key exchange with (.+)\?$/.exec(raw))) return `Voulez-vous démarrer un échange de clés avec ${m[1]} ?`;
        if ((m = /^Would you like to accept key exchange from (.+)\?$/.exec(raw))) return `Voulez-vous accepter l’échange de clés de ${m[1]} ?`;
        if ((m = /^Allow (.+) to receive key "([\s\S]+)"\?$/.exec(raw))) return `Autoriser ${m[1]} à recevoir la clé « ${m[2]} » ?`;
        if ((m = /^Accept shared key "([\s\S]+)" from (.+)\?$/.exec(raw))) return `Accepter la clé partagée « ${m[1]} » de ${m[2]} ?`;
        if ((m = /^Revoke SDC device ([^?]+)\?([\s\S]*)$/.exec(raw))) return `Révoquer l’appareil SDC ${m[1]} ?${m[2] ? '\n\nIl ne recevra plus les synchronisations de clé exacte des clients connaissant cette révocation.' : ''}`;
        if ((m = /^Identity verification question sent to (.+)$/.exec(raw))) return `Question de vérification d’identité envoyée à ${m[1]}`;
        if ((m = /^🟢 (.+) identity VERIFIED by Safety Number$/.exec(raw))) return `🟢 Identité de ${m[1]} VERIFIED par Safety Number`;
        if ((m = /^🟡 (.+) identity set to UNVERIFIED$/.exec(raw))) return `🟡 Identité de ${m[1]} définie sur UNVERIFIED`;
        if ((m = /^SDC device (.+) revoked$/.exec(raw))) return `Appareil SDC ${m[1]} révoqué`;
        if ((m = /^Plausible Deniability configured · (.+)$/.exec(raw))) return `Déni plausible configuré · ${m[1]}`;
        if ((m = /^Plausible Deniability certificates prepared: (.+)$/.exec(raw))) return `Certificats de déni plausible préparés : ${m[1]}`;
        if ((m = /^GROUP key generation (\d+) created and activated\. Private distribution is optional and can be done later from Group identity trust\.$/.exec(raw))) return `Clé GROUP génération ${m[1]} créée et activée. La distribution privée est facultative et peut être effectuée plus tard depuis la confiance d’identité du groupe.`;
        if ((m = /^GROUP key rotated; private shares sent: (\d+)$/.exec(raw))) return `Clé GROUP renouvelée ; partages privés envoyés : ${m[1]}`;
        if ((m = /^Private GROUP key shares sent: (\d+); skipped: (\d+); failed: (\d+)$/.exec(raw))) return `Partages privés de clé GROUP envoyés : ${m[1]} ; ignorés : ${m[2]} ; échecs : ${m[3]}`;
        if ((m = /^This passphrase meets the (\d+)-character minimum, but (\d+)\+ characters is recommended(?: for a portable cryptographic vault)?\. Continue\?$/.exec(raw))) return `Cette phrase secrète respecte le minimum de ${m[1]} caractères, mais ${m[2]} caractères ou plus sont recommandés. Continuer ?`;
        if (/^Disable Plausible Deniability\?/.test(raw)) return 'Désactiver le déni plausible ? Les états DURESS_SUSPECTED existants sur les contacts resteront volontairement actifs jusqu’à une nouvelle vérification d’identité.';
        if (/^Rotate the current GROUP key now\?/.test(raw)) return 'Faire tourner la clé GROUP courante maintenant ? Les correspondants non sélectionnés conserveront uniquement l’ancienne génération et ne pourront pas déchiffrer les nouveaux messages.';
      } else {
        let m;
        if ((m = /^Verrouillage auto\s*:\s*(.+)$/.exec(raw))) return `Auto-lock: ${translateText(m[1])}`;
      }
      return raw;
    }

    function localizeTree(root) {
      if (!root) return;
      const elements = root.nodeType === 1 ? [root, ...root.querySelectorAll?.('*') || []] : [];
      for (const el of elements) {
        if (!['SCRIPT', 'STYLE', 'CODE', 'PRE'].includes(String(el.tagName || '').toUpperCase())) {
          for (const child of [...(el.childNodes || [])]) {
            if (child.nodeType === 3) child.nodeValue = translateText(child.nodeValue);
          }
        }
        for (const attr of ['title', 'aria-label', 'aria-description', 'placeholder', 'data-tooltip-text', 'alt']) {
          if (el.hasAttribute?.(attr)) el.setAttribute(attr, translateText(el.getAttribute(attr)));
        }
      }
      return root;
    }

    return { detect, isFrench, pick, translateText, translateProtocolText, localizeMessage, localizeTree };
