        const comparisonImage = this.infoPopup?.getElementsByClassName('SDC_CHATCONTROL_COMPARE_IMAGE')?.[0];
        if (comparisonImage) comparisonImage.addEventListener('click', (event) => { event.preventDefault(); event.stopPropagation(); this.ShowImageLightbox(comparisonImage.src, comparisonImage.alt || (fr ? 'Comparatif de protection des messages' : 'Message protection comparison')); });
