    Discord.window.SdcCryptoV60SelfTest =
      async () => {
        const channelA =
          '123456789012345678';
        const channelB =
          '223456789012345678';
        const senderA =
          '323456789012345678';
        const senderB =
          '423456789012345678';
        const sampleText =
          'SDC v60 Crypto v3 self-test';
        const sample =
          Utils.StringToUtf8Bytes(
            sampleText
          );
        const rawKey =
          Utils.GetRandomBytes(32);
        const key =
          await Utils.AesImportKey(
            rawKey
          );

        const scopedA1 =
          await Utils.GetV3ScopedKeyId(
            key,
            channelA
          );
        const scopedA2 =
          await Utils.GetV3ScopedKeyId(
            key,
            channelA
          );
        const scopedB =
          await Utils.GetV3ScopedKeyId(
            key,
            channelB
          );
        const stableId =
          new Uint8Array(
            await Utils.Sha512_128(
              rawKey
            )
          );

        const equalBytes =
          (a, b) => {
            const aa =
              new Uint8Array(a);
            const bb =
              new Uint8Array(b);
            if (
              aa.byteLength !==
                bb.byteLength
            ) return false;
            let diff = 0;
            for (
              let i = 0;
              i < aa.byteLength;
              i++
            ) {
              diff |=
                aa[i] ^ bb[i];
            }
            return diff === 0;
          };

        const scopedIdDeterministic =
          equalBytes(
            scopedA1,
            scopedA2
          );
        const scopedIdChannelSeparated =
          !equalBytes(
            scopedA1,
            scopedB
          );
        const scopedIdNotLegacyStableHash =
          !equalBytes(
            scopedA1,
            stableId
          );

        const v3Message =
          await Utils.AesEncryptV3(
            key,
            sample,
            'message',
            channelA,
            senderA
          );
        const v3Roundtrip =
          Utils.Utf8BytesToString(
            await Utils.AesDecryptV3(
              key,
              v3Message,
              'message',
              channelA,
              senderA
            )
          ) ===
          sampleText;

        let wrongChannelRejected =
          false;
        try {
          await Utils.AesDecryptV3(
            key,
            v3Message,
            'message',
            channelB,
            senderA
          );
        } catch (_) {
          wrongChannelRejected =
            true;
        }

        let wrongSenderRejected =
          false;
        try {
          await Utils.AesDecryptV3(
            key,
            v3Message,
            'message',
            channelA,
            senderB
          );
        } catch (_) {
          wrongSenderRejected =
            true;
        }

        let crossPurposeRejected =
          false;
        try {
          await Utils.AesDecryptV3(
            key,
            v3Message,
            'file',
            channelA,
            senderA
          );
        } catch (_) {
          crossPurposeRejected =
            true;
        }

        const domainPurposes = [
          'message',
          'file',
          'filename',
          'key-share',
          'personal-key',
        ];
        const fixedNonce =
          new Uint8Array(12);
        const fixedAad =
          Utils.StringToUtf8Bytes(
            'SDC-v60-domain-key-test'
          );
        const domainCipherprints = [];

        for (
          const purpose of
          domainPurposes
        ) {
          const domainKey =
            await cryptoService.getV3DomainKey(
              key,
              purpose,
              channelA
            );
          const cipher =
            new Uint8Array(
              await crypto.subtle.encrypt(
                {
                  name: 'AES-GCM',
                  iv: fixedNonce,
                  additionalData:
                    fixedAad,
                  tagLength: 128,
                },
                domainKey,
                sample
              )
            );
          domainCipherprints.push(
            Utils.BytesToBase64(
              cipher
            )
          );
        }

        const allFiveDomainSubkeysSeparated =
          new Set(
            domainCipherprints
          ).size ===
          domainPurposes.length;

        const messageDomainKeyChannelB =
          await cryptoService.getV3DomainKey(
            key,
            'message',
            channelB
          );
        const channelBMessageCipher =
          new Uint8Array(
            await crypto.subtle.encrypt(
              {
                name: 'AES-GCM',
                iv: fixedNonce,
                additionalData:
                  fixedAad,
                tagLength: 128,
              },
              messageDomainKeyChannelB,
              sample
            )
          );
        const domainSubkeyChannelSeparated =
          domainCipherprints[0] !==
          Utils.BytesToBase64(
            channelBMessageCipher
          );

        const v3File =
          await Utils.AesEncryptV3(
            key,
            sample,
            'file',
            channelA,
            senderA
          );
        const v3Filename =
          await Utils.AesEncryptV3(
            key,
            Utils.StringToUtf8Bytes(
              'test.txt'
            ),
            'filename',
            channelA,
            senderA
          );
        const v3FileRoundtrip =
          Utils.Utf8BytesToString(
            await Utils.AesDecryptV3(
              key,
              v3File,
              'file',
              channelA,
              senderA
            )
          ) ===
          sampleText;
        const v3FilenameRoundtrip =
          Utils.Utf8BytesToString(
            await Utils.AesDecryptV3(
              key,
              v3Filename,
              'filename',
              channelA,
              senderA
            )
          ) ===
          'test.txt';

        const v3KeyShare =
          await Utils.AesEncryptV3(
            key,
            sample,
            'key-share',
            channelA,
            senderA
          );
        const v3PersonalKey =
          await Utils.AesEncryptV3(
            key,
            sample,
            'personal-key',
            channelA,
            senderA
          );
        const v3KeyShareRoundtrip =
          Utils.Utf8BytesToString(
            await Utils.AesDecryptV3(
              key,
              v3KeyShare,
              'key-share',
              channelA,
              senderA
            )
          ) ===
          sampleText;
        const v3PersonalKeyRoundtrip =
          Utils.Utf8BytesToString(
            await Utils.AesDecryptV3(
              key,
              v3PersonalKey,
              'personal-key',
              channelA,
              senderA
            )
          ) ===
          sampleText;

        rawKey.fill(0);

        const result = {
          v3EnvelopeDetected:
            Utils.IsAesV3Envelope(
              v3Message
            ),
          v3Roundtrip,
          allFiveDomainSubkeysSeparated,
          domainSubkeyChannelSeparated,
          wrongChannelRejected,
          wrongSenderRejected,
          crossPurposeRejected,
          scopedIdDeterministic,
          scopedIdChannelSeparated,
          scopedIdNotLegacyStableHash,
          v3FileRoundtrip,
          v3FilenameRoundtrip,
          v3KeyShareRoundtrip,
          v3PersonalKeyRoundtrip,
        };

        result.ok =
          Object.values(result)
            .every(Boolean);

        console.log(
          '[SDC][CRYPTO] v60 Crypto v3 self-test',
          result
        );

        return result;
      };

    Discord.window.SdcCryptoV61SelfTest = async () => {
      const initiatorId = '111111111111111111';
      const responderId = '222222222222222222';
      const channelId = '333333333333333333';
      const exchangeId = createV3ExchangeId();

      const initEph = await Utils.DhGenerateKeys();
      const respEph = await Utils.DhGenerateKeys();
      const initEphBytes = new Uint8Array(await Utils.DhExportPublicKey(initEph.publicKey));
      const respEphBytes = new Uint8Array(await Utils.DhExportPublicKey(respEph.publicKey));
      const initIdentity = await Utils.IdentityGenerateKeys();
      const respIdentity = await Utils.IdentityGenerateKeys();
      const initIdentityBytes = new Uint8Array(await Utils.IdentityExportPublicKey(initIdentity.publicKey));
      const respIdentityBytes = new Uint8Array(await Utils.IdentityExportPublicKey(respIdentity.publicKey));

      const initTranscript = canonicalJsonBytes(
        kexV3InitObject(
          exchangeId, initiatorId, responderId, channelId,
          initEphBytes, initIdentityBytes
        )
      );
      const initSignature = await Utils.IdentitySign(initIdentity.privateKey, initTranscript);
      const initSignatureValid = await Utils.IdentityVerify(
        initIdentity.publicKey, initSignature, initTranscript
      );

      const context = kexV3ContextObject(
        exchangeId, initiatorId, responderId, channelId,
        initEphBytes, respEphBytes, initIdentityBytes, respIdentityBytes
      );
      const responseTranscript = kexV3ResponseTranscript(context);
      const responseSignature = await Utils.IdentitySign(
        respIdentity.privateKey, responseTranscript
      );
      const responseSignatureValid = await Utils.IdentityVerify(
        respIdentity.publicKey, responseSignature, responseTranscript
      );

      const initViewOfResp = await Utils.DhImportPublicKey(respEphBytes);
      const respViewOfInit = await Utils.DhImportPublicKey(initEphBytes);
      const initMaterial = await deriveKexV3Material(
        initEph.privateKey, initViewOfResp, context
      );
      const respMaterial = await deriveKexV3Material(
        respEph.privateKey, respViewOfInit, context
      );
      const conversationKeysMatch = constantTimeBytesEqual(
        initMaterial.conversationKeyBytes, respMaterial.conversationKeyBytes
      );
      const confirmationKeysMatch = constantTimeBytesEqual(
        initMaterial.confirmationKeyBytes, respMaterial.confirmationKeyBytes
      );
      const transcriptHashesMatch = constantTimeBytesEqual(
        initMaterial.transcriptHash, respMaterial.transcriptHash
      );

      const responderProof = await kexV3Proof(
        respMaterial.confirmationKeyBytes,
        respMaterial.transcriptHash,
        'RESPONDER',
        exchangeId
      );
      const expectedResponderProof = await kexV3Proof(
        initMaterial.confirmationKeyBytes,
        initMaterial.transcriptHash,
        'RESPONDER',
        exchangeId
      );
      const responderKeyConfirmation = constantTimeBytesEqual(
        responderProof, expectedResponderProof
      );

      const differentContext = { ...context, channelId: '444444444444444444' };
      const wrongContextMaterial = await deriveKexV3Material(
        initEph.privateKey, initViewOfResp, differentContext
      );
      const contextSeparation = !constantTimeBytesEqual(
        initMaterial.conversationKeyBytes, wrongContextMaterial.conversationKeyBytes
      );

      const replayProbe = createV3ExchangeId();
      rememberConsumedV3ExchangeId(replayProbe, Date.now(), false);
      let replayRejected = false;
      try {
        assertNewInboundV3Exchange(
          replayProbe, responderId, channelId
        );
      } catch (_) {
        replayRejected = true;
      } finally {
        consumedV3ExchangeIds.delete(replayProbe);
      }

      const wrappingRaw = Utils.GetRandomBytes(32);
      const wrappingKey = await Utils.AesImportKey(wrappingRaw);
      const scopedId = await Utils.GetV3ScopedKeyId(wrappingKey, channelId);
      const shareObject = {
        context: {
          channelId,
          recipientId: responderId,
          senderId: initiatorId,
          wrappingScopedKeyId: Utils.BytesToBase64url(scopedId)
        },
        key: {
          bytes: Utils.BytesToBase64url(Utils.GetRandomBytes(32)),
          descriptor: 'v61 self-test',
          hidden: false,
          sharedChannels: [],
          type: 'CONVERSATION'
        },
        protocol: 3,
        request: null,
        status: 'OK',
        type: 'KEY_SHARE'
      };
      const shareEnvelope = await Utils.AesEncryptV3(
        wrappingKey, canonicalJsonBytes(shareObject),
        'key-share', channelId, initiatorId
      );
      const shareClear = Utils.Utf8BytesToString(
        await Utils.AesDecryptV3(
          wrappingKey, shareEnvelope,
          'key-share', channelId, initiatorId
        )
      );
      const keyShareCanonicalRoundtrip =
        shareClear === canonicalJson(shareObject);
      const tamperedShare = new Uint8Array(shareEnvelope).slice();
      tamperedShare[tamperedShare.length - 1] ^= 1;
      let tamperedKeyShareRejected = false;
      try {
        await Utils.AesDecryptV3(
          wrappingKey, tamperedShare,
          'key-share', channelId, initiatorId
        );
      } catch (_) {
        tamperedKeyShareRejected = true;
      }

      for (const bytes of [
        initMaterial.conversationKeyBytes,
        initMaterial.confirmationKeyBytes,
        respMaterial.conversationKeyBytes,
        respMaterial.confirmationKeyBytes,
        wrongContextMaterial.conversationKeyBytes,
        wrongContextMaterial.confirmationKeyBytes,
        wrappingRaw
      ]) {
        try { bytes.fill(0); } catch (_) {}
      }

      const result = {
        exchangeIdIs256Bits: Utils.Base64urlToBytes(exchangeId).byteLength === 32,
        initSignatureValid,
        responseSignatureValid,
        conversationKeysMatch,
        confirmationKeysMatch,
        transcriptHashesMatch,
        responderKeyConfirmation,
        contextSeparation,
        replayRejected,
        keyShareCanonicalRoundtrip,
        tamperedKeyShareRejected
      };
      result.ok = Object.values(result).every(Boolean);
      console.log('[SDC][CRYPTO] v61 control-plane self-test', result);
      return result;
    };

    Discord.window.SdcCryptoV63SelfTest = async () => {
      const a = createV3ExchangeId();
      const b = createV3ExchangeId();
      const winnerAB = chooseV3SimultaneousInitWinner(a, b);
      const winnerBA = chooseV3SimultaneousInitWinner(b, a);
      const deterministicCollisionArbitration =
        winnerAB === winnerBA && winnerAB === (a < b ? a : b);

      const replayProbe = createV3ExchangeId();
      rememberConsumedV3ExchangeId(replayProbe, Date.now(), false);
      const serializedReplay = serializePersistentV3ReplayCache();
      const replaySerializationContainsProbe =
        Number.isFinite(serializedReplay[replayProbe]) &&
        serializedReplay[replayProbe] > Date.now();
      consumedV3ExchangeIds.delete(replayProbe);

      const packetA =
        `*type*: \`KEX ACK\`\n` +
        `*protocol*: \`3\`\n` +
        `*exchangeId*: \`${a}\`\n` +
        `*transcriptHash*: \`abc\`\n` +
        `*keyConfirm*: \`def\`\n` +
        `*signature*: \`ghi\``;
      const packetB = packetA.replace('`def`', '`deg`');
      const fingerprintA1 = await v3KexPacketFingerprint('ACK', packetA);
      const fingerprintA2 = await v3KexPacketFingerprint('ACK', packetA);
      const fingerprintB = await v3KexPacketFingerprint('ACK', packetB);
      const packetFingerprintStable = fingerprintA1 === fingerprintA2;
      const modifiedPacketFingerprintSeparated = fingerprintA1 !== fingerprintB;

      const completedRespFingerprint = 'v68.0.5-self-test-authenticated-resp';
      const completedReceiptProbe = buildCompletedV3InitiatorReceipt(
        { responsePacketFingerprint: completedRespFingerprint },
        '111111111111111111',
        '333333333333333333',
        fingerprintA1
      );
      rememberCompletedV3KexReceipt(a, completedReceiptProbe);
      const receipt = getCompletedV3KexReceipt(a);
      const completedReceiptRoundtrip =
        receipt?.role === 'INITIATOR' &&
        receipt?.ackPacketFingerprint === fingerprintA1 &&
        receipt?.responsePacketFingerprint === completedRespFingerprint;
      const completedRespDuplicateAcceptedIdempotently =
        classifyCompletedV3ResponseDuplicate(
          receipt, '111111111111111111', '333333333333333333', completedRespFingerprint
        ) === 'EXACT_COMPLETED_DUPLICATE';
      const completedRespModifiedRejected =
        classifyCompletedV3ResponseDuplicate(
          receipt, '111111111111111111', '333333333333333333', completedRespFingerprint + '-modified'
        ) === 'REJECT';
      const completedRespWrongPeerRejected =
        classifyCompletedV3ResponseDuplicate(
          receipt, '222222222222222222', '333333333333333333', completedRespFingerprint
        ) === 'REJECT';
      const completedReceiptContainsNoKexSecrets =
        !['conversationKeyBytes', 'confirmationKeyBytes', 'privateKey', 'transcriptHash']
          .some((field) => Object.prototype.hasOwnProperty.call(receipt || {}, field));
      completedV3KexReceipts.delete(a);

      const retryPolicyBounded =
        CONFIG.timing.keyExchangeRetryIntervalMs > 0 &&
        CONFIG.timing.keyExchangeMaxRetransmits >= 1 &&
        CONFIG.timing.keyExchangeMaxRetransmits <= 10 &&
        CONFIG.timing.keyExchangeMaxDuplicateResponses >= 1 &&
        CONFIG.timing.keyExchangeMaxDuplicateResponses <= 20;

      const result = {
        deterministicCollisionArbitration,
        replaySerializationContainsProbe,
        packetFingerprintStable,
        modifiedPacketFingerprintSeparated,
        completedReceiptRoundtrip,
        completedRespDuplicateAcceptedIdempotently,
        completedRespModifiedRejected,
        completedRespWrongPeerRejected,
        completedReceiptContainsNoKexSecrets,
        retryPolicyBounded,
      };
      result.ok = Object.values(result).every(Boolean);
      console.log('[SDC][CRYPTO] v63 KEX robustness self-test', result);
      return result;
    };

