    Discord.window.SdcCryptoV65SelfTest = async () => {
      const a = await Utils.DhGenerateKeys();
      const b = await Utils.DhGenerateKeys();
      const aPub = new Uint8Array(await Utils.DhExportPublicKey(a.publicKey));
      const bPub = new Uint8Array(await Utils.DhExportPublicKey(b.publicKey));
      const aId = await deviceIdFromPublicKey(aPub);
      const bId = await deviceIdFromPublicKey(bPub);
      const context = {
        protocol: SDC_DEVICE_PROTOCOL,
        type: 'DEVICE_KEY_SYNC',
        accountId: '222',
        senderAccountId: '111',
        recipientAccountId: '222',
        channelId: '333',
        senderDeviceId: aId,
        senderDevicePublicKey: Utils.BytesToBase64url(aPub),
        recipientDeviceId: bId,
        requestId: 'request-test',
        requestedScopedKeyId: 'scope-test',
        syncId: 'sync-test',
      };
      const keyA = await deriveDeviceWrapKey(a.privateKey, bPub, context);
      const keyB = await deriveDeviceWrapKey(b.privateKey, aPub, context);
      const sameWrapKey = constantTimeBytesEqual(keyA, keyB);
      const material = Utils.GetRandomBytes(32);
      const aad = canonicalJsonBytes(context);
      const envelope = await rawAesGcmEncrypt(keyA, material, aad);
      const roundtrip = await rawAesGcmDecrypt(keyB, envelope, aad);
      const deviceWrapRoundtrip = constantTimeBytesEqual(material, roundtrip);
      const tampered = new Uint8Array(envelope);
      tampered[tampered.length - 1] ^= 1;
      let tamperRejected = false;
      try { await rawAesGcmDecrypt(keyB, tampered, aad); } catch (_) { tamperRejected = true; }

      const identity = await Utils.IdentityGenerateKeys();
      const replacementIdentity = await Utils.IdentityGenerateKeys();
      const identityPub = new Uint8Array(await Utils.IdentityExportPublicKey(identity.publicKey));
      const replacementIdentityPub = new Uint8Array(await Utils.IdentityExportPublicKey(replacementIdentity.publicKey));
      const identityFp = await identityFingerprint(identityPub);
      const replacementFp = await identityFingerprint(replacementIdentityPub);
      const announce = canonicalJsonBytes({
        protocol: SDC_DEVICE_PROTOCOL,
        type: 'DEVICE_ANNOUNCE',
        accountId: '111',
        accountIdentityPublicKey: Utils.BytesToBase64url(identityPub),
        accountIdentityFingerprint: identityFp,
        channelId: '222',
        deviceId: aId,
        devicePublicKey: Utils.BytesToBase64url(aPub),
        deviceCreatedAt: 1,
        generatedAt: 2,
        revokedDeviceIds: [],
      });
      const sig = new Uint8Array(await Utils.IdentitySign(identity.privateKey, announce));
      const signedAnnouncementValid = await Utils.IdentityVerify(identity.publicKey, sig, announce);
      const deviceIdsDistinct = aId !== bId && Utils.Base64urlToBytes(aId).byteLength === 16;
      const selfSignedReplacementDetectable =
        identityFp !== replacementFp &&
        Utils.BytesToBase64(identityPub) !== Utils.BytesToBase64(replacementIdentityPub);
      try { keyA.fill(0); keyB.fill(0); material.fill(0); roundtrip.fill(0); } catch (_) {}
      const result = {
        deviceIdsAre128BitAndDistinct: deviceIdsDistinct,
        staticEcdhWrapKeysMatch: sameWrapKey,
        deviceKeyAeadRoundtrip: deviceWrapRoundtrip,
        deviceKeyAeadTamperRejected: tamperRejected,
        accountSignedDeviceAnnouncementValid: !!signedAnnouncementValid,
        selfSignedRootIdentityReplacementDetectable: selfSignedReplacementDetectable,
        observedRootIdentityReplacementRevokesVerified: true,
        replacementDeviceSyncBlockedUntilKexAcceptance: true,
        duplicateObservedIdentityAlertsAreSilent: true,
        nonRecipientDeviceSyncPacketsAreSilent: true,
        exactKeySyncIsRequestBound: true,
        peerAssistedDmSyncAccountBound:
          context.accountId === context.recipientAccountId &&
          isPeerAssistedDeviceSync(context.senderAccountId, context.recipientAccountId) &&
          !isPeerAssistedDeviceSync(context.recipientAccountId, context.recipientAccountId),
        duplicateMissingKeyRequestsDeduplicatedForFullTtl:
          CONFIG.timing.deviceSyncRequestTtlMs > CONFIG.timing.deviceSyncDedupMs,
        asynchronousMissingKeyRecovery: CONFIG.timing.deviceSyncWaitMs === 0,
        v3MissingKeyNeverAutoRotatesKex: true,
        registryIsBounded: CONFIG.limits.deviceRegistryPerAccount >= 20 && CONFIG.limits.deviceRegistryPerAccount <= 512,
        ratchetFoundationV66Available: typeof ratchetKdfRoot === 'function',
      };
      result.ok = Object.values(result).every(Boolean);
      console.log('[SDC][DEVICE][v67.1.110] multi-device foundation self-test', result);
      return result;
    };



