    if (offset + 2 > bytes.byteLength) throw new Error('Async prekey compact signature length missing');
    const unsignedBytes = bytes.slice(0, offset);
    const signatureLength = view.getUint16(offset, false); offset += 2;
    if (signatureLength < 64 || offset + signatureLength !== bytes.byteLength)
      throw new Error('Invalid async prekey compact signature length');
