      protocol: 'SDC-V69.2-HYBRID-ASYNC-ENTRY',
      version: SDC_HYBRID_ASYNC_VERSION,
      messageId: String(top.messageId || ''),
      generatedAt: Number(top.generatedAt || 0),
      accountId: String(top.accountId || ''),
      recipientAccountId: String(top.recipientAccountId || ''),
      channelId: String(top.channelId || ''),
      senderDeviceId: String(top.senderDeviceId || ''),
      senderDevicePublicKey: String(top.senderDevicePublicKey || ''),
      senderEphemeralPublicKey: String(top.senderEphemeralPublicKey || ''),
      recipientDeviceId: String(entry.recipientDeviceId || ''),
      recipientPrekeyId: String(entry.recipientPrekeyId || ''),
      recipientPqPrekeyId: String(entry.recipientPqPrekeyId || ''),
      pqCiphertext: Utils.BytesToBase64url(entry.pqCiphertext instanceof Uint8Array ? entry.pqCiphertext : new Uint8Array(entry.pqCiphertext || [])),
      profile: SDC_HYBRID_ASYNC_PROFILE,
      purpose: String(top.purpose || 'USER_MESSAGE'),
