        wink: '😉',
        sob: '😭',
        cry: '😢',
        angry: '😠',
        rage: '😡',
        thinking: '🤔',
        eyes: '👀',
        heart: '❤️',
        orange_heart: '🧡',
        yellow_heart: '💛',
        green_heart: '💚',
        blue_heart: '💙',
        purple_heart: '💜',
        black_heart: '🖤',
        white_heart: '🤍',
        broken_heart: '💔',
        fire: '🔥',
        tada: '🎉',
        rocket: '🚀',
        wave: '👋',
        clap: '👏',
        pray: '🙏',
        thumbsup: '👍',
        thumbsdown: '👎',
        ok_hand: '👌',
        muscle: '💪',
        point_right: '👉',
        point_left: '👈',
        100: '💯',
        warning: '⚠️',
        check: '✅',
        x: '❌',
        skull: '💀',
        clown: '🤡',
        poop: '💩',
        sunglasses: '😎',
        innocent: '😇',
        neutral_face: '😐',
        expressionless: '😑',
        unamused: '😒',
        sweat_smile: '😅',
        rofl: '🤣',
        laughing: '😆',
        stuck_out_tongue: '😛',
        open_mouth: '😮',
        face_holding_back_tears: '🥹',
        pleading_face: '🥺',
        slightly_smiling_face: '🙂',
        frowning_face: '☹️',
        disappointed: '😞',
        weary: '😩',
        tired_face: '😫',
        scream: '😱',
        fearful: '😨',
        cold_sweat: '😰',
        sweat: '😓',
        confounded: '😖',
        flushed: '😳',
        kissing_heart: '😘',
