      const top =
        Number.isFinite(liveFirstLineTop)
          ? liveFirstLineTop
          : editorRect.top +
            Number(
              geometry.editorTextInsetY || 0
            );

      const right =
        editorRect.right;

      const height =
        active.secureInputHeight ||
        22;

      return {
        left,
        top,
        width: Math.max(
          1,
          right - left
        ),
        height,
      };
