          draftSalt:
            draftSalt,
          lastSecureVisualWidth:
            0,
          lastSentSecureInputMaxHeight:
            null,
          lastParentLayoutHeight:
            null,
          layoutObserver:
            null,
          layoutMutationObserver:
            null,
