          keyReady: false,
          protectionIndicatorVisible: false,
          protectionPlaceholderLogged: false,
          sandboxAeadBackend: null,
          frameInitSent: false,
          frameInitNetworkKeyId: networkKeyId,
          frameInitV3MessageKey: frameKeys.message,
