          frameInitPdDecoyKey: pdDecoyFrameKey,
          frameInitPdDecoyOwnerId: pdDecoyFrameContext?.ownerId || null,
          frameInitPdDecoyPeerId: pdDecoyFrameContext?.peerId || null,
          frameInitPdDecoyDeviceId: pdDecoyFrameContext?.deviceId || null,
          frameInitPdDecoyPublicKey: pdDecoyFrameContext?.publicKey || null,
          frameInitLocalDeviceId: historyLocalDevice?.deviceId || null,
          frameInitSenderId: senderId,
          mentionCandidates: this.getSecureMentionCandidates(config.channelId),
          mentionState: null,
          mentionPopupState: null,
          mentionAliases: [],
          mentionDisplayLastValue: '',

          inputBlocker: null,
          nativeEmojiObserver: null,
          nativeEmojiEvacuationScheduled: false,

