          nativeEditModeArmed: false,
          nativeEditMessageCapturedAt: 0,
          nativeEditMessageId: '',
          nativeEditLocalEchoId: '',
          nativeEditMarkerSuppression: null,
          nativeEditPresentationLastLogAt: 0,
          nativeEditAttachmentScopedKeyId: null,
          nativeEditAttachmentFileFsDescriptors: [],
          nativeEditAttachmentCount: 0,
          nativeShortcutInProgress: false,
          nativeEditSubmissionPending: false,
          nativeReplyPendingLast: false,

