            `${config.channelId}:${initialNativeDraft.length}:${initialNativeDraft}`;

          const sameDeferredDraft =
            this.deferredNativeDraft?.fingerprint === draftFingerprint &&
            this.deferredNativeDraft?.editor === editor;

