        pinnedFileSubmit?.nativeSecureFileSubmitInProgress === true &&
        pinnedFileSubmit.channelId === config.channelId &&
        pinnedFileSubmit.keyHash === config.keyHash &&
        pinnedFileSubmit.cryptoProtocol === config.cryptoProtocol &&
        pinnedFileSubmit.textCryptoProtocol === this.getSecureTextCryptoProtocol(config.channelId)
