            pinnedFileSubmit.mainEditor = replacementEditor;
            pinnedFileSubmit.composerRoot = replacementComposerRoot;
            pinnedFileSubmit.mainComposerRoot = replacementComposerRoot;
            pinnedFileSubmit.nativeState = replacementNativeState;
            pinnedFileSubmit.mainNativeState = replacementNativeState;
            pinnedFileSubmit.placeholder = replacementPlaceholder;
            pinnedFileSubmit.mainPlaceholder = replacementPlaceholder;
            pinnedFileSubmit.placeholderState = replacementPlaceholderState;
            pinnedFileSubmit.mainPlaceholderState = replacementPlaceholderState;
            pinnedFileSubmit.theme = replacementTheme;
            pinnedFileSubmit.mainTheme = replacementTheme;
