            editor;

          active.mainComposerRoot =
            replacementMainRoot;

          active.mainNativeState =
            replacementMainState;

          active.mainPlaceholder =
            replacementMainPlaceholder;

          active.mainPlaceholderState =
            replacementPlaceholderState;

