    Discord.detour_uploadFiles = function (params) {
      const receiver =
        this;

      const args =
        arguments;

      return (async () => {
        const channelId =
          params?.channelId;

        clearAttachmentBlockedChannels.add(
          channelId
        );

        let allowed =
          false;

        try {
          allowed =
            await handleUploadFiles(
              params
            );

          if (
            allowed !== true
          ) {
            // Keep the user's draft/attachment card intact for a retry. Most
            // importantly: never call original_uploadFiles() on failure.
            return false;
          }

          fixPendingReply(
            params.options
          );

          const result =
            await Discord.original_uploadFiles.apply(
              receiver,
              args
            );

          Discord.dispatch({
            type:
              'UPLOAD_ATTACHMENT_CLEAR_ALL_FILES',
            channelId,
            draftType: 0,
          });

          return result;
        } finally {
          clearAttachmentBlockedChannels.delete(
            channelId
          );
        }
      })();
    };

